const D = { energy: .62, scale: 1, density: .5, speed: 1, pitch: .5, hue: 205, x: .5, y: .5, style: 'cpk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style, u = Math.min(width, height);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const H = ((P.hue%360)+360)%360;

// base-pair CPK-ish hues [A,T,G,C]
let baseHues, backHue, backSat, groundV, groundH, wire, paper;
if (st === 'wireframe')   { baseHues=[196,196,196,196]; backHue=196; backSat=30; groundV=10; groundH=205; wire=true; paper=false; }
else if (st === 'ribbon') { baseHues=[16,340,150,196]; backHue=H; backSat=35; groundV=12; groundH=H; wire=false; paper=false; }
else if (st === 'neon')   { baseHues=[315,190,110,50]; backHue=H; backSat=70; groundV=6; groundH=H; wire=false; paper=false; }
else if (st === 'ink')    { baseHues=[20,20,20,20]; backHue=24; backSat=20; groundV=54; groundH=36; wire=false; paper=true; }
else /* cpk */            { baseHues=[8,205,130,52]; backHue=H; backSat=28; groundV=9; groundH=H; wire=false; paper=false; }

// helices (seeded depth + phase), rebuilt on seed/density/size
const nH = 3 + Math.round(P.density*5);
const hkey = width+'x'+height+'|'+P.seed+'|'+nH;
if (S.hkey !== hkey) {
  S.hkey = hkey; S.hel = [];
  for (let i = 0; i < nH; i++) {
    S.hel.push({ z: fr(i*3.1), xf: (i+0.5)/nH + (fr(i*7.7)-0.5)*0.06, p0: fr(i*4.4)*6.28,
                 bases: Array.from({length: 40}, (_,k) => fr(i*13.1 + k*2.3) < 0.5 ? 0 : 2) });  // AT(0) or GC(2)
  }
  S.hel.sort((a,b) => a.z - b.z);   // back to front
}

// background: dark vertical gradient + drifting solvent motes
const BW = Math.max(360, Math.min(560, Math.round(width/3)));
const BH = Math.max(160, Math.round(BW*height/width));
if (!S.bg || S.bkey !== BW+'x'+BH+'|'+st) {
  S.bkey = BW+'x'+BH+'|'+st; const g = S.bg || (S.bg = createGraphics(BW,BH));
  g.colorMode(g.HSB,360,100,100,100); g.pixelDensity(1); g.noStroke();
  for (let y=0;y<BH;y++){ const f=y/BH; g.fill(groundH, paper?10:45, groundV*(0.8+0.5*Math.abs(f-0.5)*2)); g.rect(0,y,BW,1); }
  S.bg = g;
}
push();
image(S.bg, 0, 0, width, height);
// solvent motes drift
blendMode(paper?BLEND:ADD); noStroke();
const nm = 60;
for (let i=0;i<nm;i++){ const mx=(fr(i*1.7)*width + Math.sin(K.t*0.2+i)*u*0.02)%width;
  const my=(fr(i*2.9)*height + K.t*u*0.6*(0.3+fr(i*3.3)) )%height;
  fill(groundH, 30, paper?30:55, paper?4:8); ellipse(mx, my, u*0.006, u*0.006); }

const rot = K.t*(0.5 + P.speed*0.9);
const wob = Math.sin(K.t*0.33)*0.4 + Math.sin(K.t*0.61+1.2)*0.25;   // incommensurate axial wobble
const travel = K.t*(0.15 + P.speed*0.3);
const twist = (0.85 + P.pitch*1.3) / u * 90;                        // helical pitch
const glow = 0.6 + P.energy*0.9;
const beat = 0.85 + K.pulse*0.25 + A.rms*0.5;

for (let hi = 0; hi < S.hel.length; hi++) {
  const hx = S.hel[hi], z = hx.z;
  const depth = 0.45 + z*0.75;
  const xc = (hx.xf + (P.x-0.5)*0.4)*width;                 // column position (P.x shifts bundle)
  const rad = u*(0.045 + 0.05*P.scale)*depth;
  const bw = Math.max(1.2, u*0.005*depth*(0.7+P.energy*0.6));
  const aZ = (0.4 + 0.6*z) * glow;
  const step = u*0.016;
  const yTop = -step*2, yBot = height + step*2;
  let rungK = 0;
  for (let y = yTop; y < yBot; y += step) {
    const th = y*twist*0.02 + rot + hx.p0 + travel + wob*Math.sin(y*0.004);
    const c = Math.cos(th), s2 = Math.sin(th);            // s2 = depth of strand A (front if >0)
    const ax = xc + rad*c, bx = xc - rad*c;               // antiparallel strands
    const dA = 0.5 + 0.5*s2, dB = 0.5 - 0.5*s2;           // per-strand depth cue
    // base-pair rung (every 3rd sample), drawn behind strands
    if ((rungK % 3) === 0) {
      const bp = hx.bases[((rungK/3)|0) % hx.bases.length];
      const hA = baseHues[bp], hB = baseHues[bp+1];
      const midx = xc, thin = bw*0.8;
      stroke(hA, wire?55:80, wire?85:88, (wire?55:70)*aZ*beat*(0.6+dA*0.6)); strokeWeight(thin);
      line(ax, y, midx, y);
      stroke(hB, wire?55:80, wire?88:90, (wire?55:70)*aZ*beat*(0.6+dB*0.6)); strokeWeight(thin);
      line(midx, y, bx, y);
    }
    // backbone points (front strand brighter/bigger)
    noStroke();
    fill(backHue, backSat, paper?24:88, (paper?70:60)*aZ*(0.5+dA*0.9));
    ellipse(ax, y, bw*1.8*(0.6+dA*0.7), bw*1.8*(0.6+dA*0.7));
    fill(backHue, backSat, paper?24:82, (paper?70:60)*aZ*(0.5+dB*0.9));
    ellipse(bx, y, bw*1.8*(0.6+dB*0.7), bw*1.8*(0.6+dB*0.7));
    rungK++;
  }
}
pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
if (P.alpha < 100) { push(); noStroke(); fill(0,0,0,100-P.alpha); rect(0,0,width,height); pop(); }
